// Every category the pipeline can produce, and its direction. This object is the single
// source of truth: a category with no direction here does not exist, so one can never be
// added to the vocabulary while silently defaulting to "spend".
const DIRECTION = {
  groceries: 1,
  transport: 1,
  utilities: 1,
  dining: 1,
  refund: -1,
  other: 1,
};

// Categories recognised in the export. 'other' is the bucket for everything else, not a
// value the bank sends, so it is not "known".
const KNOWN_CATEGORIES = Object.keys(DIRECTION).filter((c) => c !== 'other');

function normalizeCategory(raw) {
  const category = String(raw || '').trim().toLowerCase();
  return KNOWN_CATEGORIES.includes(category) ? category : 'other';
}

// Signed amount: positive means money left the account, negative means it came back.
function signedAmount(record) {
  const category = normalizeCategory(record.category);
  return Math.abs(record.amount) * DIRECTION[category];
}

module.exports = { KNOWN_CATEGORIES, DIRECTION, normalizeCategory, signedAmount };

